        """根据主题更新本页样式（浅色 / 深色）"""
        dark = theme == "dark"
        self._header.setStyleSheet("background-color: #26272d;" if dark else "background-color: #ffffff;")
        self._title.setStyleSheet("font-size: 18px; font-weight: 600; color: #e6e7eb;" if dark else "font-size: 18px; font-weight: 600; color: #333;")
