import subprocess
def kill(name):
    try:
        out = subprocess.check_output(['tasklist', '/FI', f'IMAGENAME eq {name}', '/FO', 'CSV'], stderr=subprocess.DEVNULL)
        for line in out.decode('gbk', errors='ignore').strip().splitlines()[1:]:
            parts = line.split(',')
            if len(parts) > 1:
                pid = parts[1].strip('\"')
                subprocess.run(['taskkill', '/F', '/PID', pid], capture_output=True)
                print(f'killed {name} pid={pid}')
    except Exception as e:
        print(name, 'err:', e)
